<?php
session_start();
if (!isset($_SESSION["user_id"])) { die("Please log in first."); }
require "db.php";
$user_id = (int)$_SESSION["user_id"];
$task_id = isset($_GET["task_id"]) ? (int)$_GET["task_id"] : 0;
$query = mysqli_prepare($conn, "SELECT t.*,a.status AS assignment_status FROM tasks t JOIN task_assignments a ON a.task_id=t.task_id WHERE t.task_id=? AND a.user_id=?");
mysqli_stmt_bind_param($query, "ii", $task_id, $user_id); mysqli_stmt_execute($query); $task = mysqli_fetch_assoc(mysqli_stmt_get_result($query));
if (!$task) { die("Task not found or it is not assigned to you."); }
?>
